function renameColumn(table, oldName, newName) {
  const cols=columns(table);
  if(cols.includes(oldName)&&!cols.includes(newName)) db.exec(`ALTER TABLE ${table} RENAME COLUMN ${oldName} TO ${newName}`);
}

