function migrateDifficultyLevelRange(){
 const names=['task_type_weights','task_type_capacities','deliverable_task_ratios','project_task_plan','tasks'];
 const rebuild=[];
 for(const name of names){const entry=db.prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name=?").get(name);if(entry?.sql&&/difficulty_level\s+BETWEEN\s+1\s+AND\s+6/i.test(entry.sql))rebuild.push({name,sql:entry.sql,indexes:db.prepare("SELECT sql FROM sqlite_master WHERE type='index' AND tbl_name=? AND sql IS NOT NULL").all(name).map(x=>x.sql)})}
 if(!rebuild.length)return;
 fs.mkdirSync(backupDirectory,{recursive:true});const backupPath=path.join(backupDirectory,'ruang-proyek-'+new Date().toISOString().replace(/[:.]/g,'-')+'-pre-level8.sqlite');db.exec("VACUUM INTO '"+backupPath.replace(/'/g,"''")+"'");
 db.exec('PRAGMA foreign_keys=OFF; BEGIN IMMEDIATE');
 try{for(const item of rebuild){const temp=item.name+'_level8_migration';db.exec('DROP TABLE IF EXISTS "'+temp+'"');const matcher=new RegExp('^(CREATE TABLE\\s+(?:IF NOT EXISTS\\s+)?)(?:"?'+item.name+'"?)','i');const create=item.sql.replace(matcher,'$1"'+temp+'"').replace(/difficulty_level\s+BETWEEN\s+1\s+AND\s+6/ig,'difficulty_level BETWEEN 1 AND 8');db.exec(create);db.exec('INSERT INTO "'+temp+'" SELECT * FROM "'+item.name+'"');db.exec('DROP TABLE "'+item.name+'"');db.exec('ALTER TABLE "'+temp+'" RENAME TO "'+item.name+'"');for(const indexSql of item.indexes)db.exec(indexSql)}db.exec('COMMIT')}catch(error){try{db.exec('ROLLBACK')}catch{}throw error}finally{db.exec('PRAGMA foreign_keys=ON')}
}
migrateDifficultyLevelRange();
