  const task=id=>db.prepare('SELECT * FROM tasks WHERE task_id=?').get(id);
  if(a.type==='generalWork.add'){const title=String(a.title||'').trim(),note=String(a.note||'').trim(),definition=normalizeGeneralWorkDefinition(a);if(!title)throw Error('Nama pekerjaan wajib diisi');let ownerUserId=user.user_id,personnelId=user.personnel_id,ownerName=user.personnel_name||user.username;if(user.access_role==='admin'){personnelId=String(a.personnel_id||'');const pic=db.prepare("SELECT p.personnel_id,p.personnel_name,u.user_id FROM personnel p JOIN users u ON u.user_id=p.user_id WHERE p.personnel_id=? AND u.account_status='active'").get(personnelId);if(!pic)throw Error('Pilih PIC dengan akun aktif');ownerUserId=pic.user_id;ownerName=pic.personnel_name}else if(!personnelId)throw Error('Akun ini belum terhubung ke data personel');const id=uuid();db.prepare("INSERT INTO general_work(work_id,owner_user_id,personnel_id,owner_name,title,note,definition_type,task_type_id,difficulty_level,status) VALUES (?,?,?,?,?,?,?,?,?,'Pending')").run(id,ownerUserId,personnelId,ownerName,title,note,definition.definition_type,definition.task_type_id,definition.difficulty_level);notifyGeneralWork(ownerUserId,id,title,'You were assigned a general task',user);return {message:'Pekerjaan general ditambahkan'}}
  if(a.type==='generalWork.update'){const w=db.prepare('SELECT * FROM general_work WHERE work_id=?').get(a.work_id);if(!w)throw Error('Pekerjaan general tidak ditemukan');if(user.access_role!=='admin'&&w.owner_user_id!==user.user_id)throw Object.assign(Error('Kamu hanya bisa mengedit pekerjaan milikmu'),{status:403});const title=String(a.title||'').trim(),definition=normalizeGeneralWorkDefinition(a);if(!title)throw Error('Nama pekerjaan wajib diisi');let ownerUserId=w.owner_user_id,personnelId=w.personnel_id,ownerName=w.owner_name;if(user.access_role==='admin'){personnelId=String(a.personnel_id||'');const pic=db.prepare("SELECT p.personnel_id,p.personnel_name,u.user_id FROM personnel p JOIN users u ON u.user_id=p.user_id WHERE p.personnel_id=? AND u.account_status='active'").get(personnelId);if(!pic)throw Error('Pilih PIC dengan akun aktif');ownerUserId=pic.user_id;ownerName=pic.personnel_name}const completedWeight=w.status==='Done'?(definition.definition_type==='Defined'?generalTaskWeight(definition.task_type_id,definition.difficulty_level):Number(db.prepare('SELECT COALESCE(SUM(duration_seconds),0) seconds FROM general_work_timer_sessions WHERE work_id=?').get(w.work_id).seconds)/3600/7):w.completed_weight;db.prepare('UPDATE general_work SET title=?,owner_user_id=?,personnel_id=?,owner_name=?,definition_type=?,task_type_id=?,difficulty_level=?,completed_weight=?,updated_at=CURRENT_TIMESTAMP WHERE work_id=?').run(title,ownerUserId,personnelId,ownerName,definition.definition_type,definition.task_type_id,definition.difficulty_level,completedWeight,w.work_id);const changed=title!==w.title||definition.definition_type!==w.definition_type||definition.task_type_id!==w.task_type_id||Number(definition.difficulty_level||0)!==Number(w.difficulty_level||0)||ownerUserId!==w.owner_user_id;if(changed)notifyGeneralWork(ownerUserId,w.work_id,title,ownerUserId!==w.owner_user_id?'You were assigned a general task':'General task details were updated',user);return {message:'Pekerjaan general diperbarui'}}
